// Recycling is bounded by the visible viewport, independently of item count.
export function createVirtualList(element,{items=[],rowHeight=40,label=item=>String(item?.text??item),select=()=>{},selected=-1}={}){
  const document=element.ownerDocument,content=document.createElement('div'),pool=[];content.style.position='relative';element.replaceChildren(content);element.style.overflow='auto';element.style.position||='relative';element.setAttribute('role','listbox');let disposed=false,current=items,chosen=selected;
  function update(){if(disposed)return;content.style.height=current.length*rowHeight+'px';const height=element.clientHeight||160,start=Math.max(0,Math.min(Math.max(0,current.length-1),Math.floor(element.scrollTop/rowHeight)-2)),count=Math.min(current.length-start,Math.ceil(height/rowHeight)+5);while(pool.length<count){const row=document.createElement('button');row.type='button';row.setAttribute('role','option');Object.assign(row.style,{position:'absolute',left:'0',width:'100%',textAlign:'start',border:'0',margin:'0',background:'transparent',color:'inherit'});row.onclick=()=>{chosen=Number(row.dataset.index);select(chosen,current[chosen]);update();};pool.push(row);content.append(row);}for(let i=0;i<pool.length;i++){const row=pool[i],index=start+i;row.hidden=i>=count;if(row.hidden)continue;row.dataset.index=String(index);row.style.top=index*rowHeight+'px';row.style.height=rowHeight+'px';row.textContent=label(current[index],index);row.setAttribute('aria-posinset',String(index+1));row.setAttribute('aria-setsize',String(current.length));row.setAttribute('aria-selected',String(index===chosen));row.tabIndex=index===chosen?0:-1;row.style.background=index===chosen?'var(--ui-accent, #365778)':'transparent';}}
  function key(event){if(!['ArrowDown','ArrowUp','Home','End','Enter',' '].includes(event.key))return;event.preventDefault();if(event.key==='Enter'||event.key===' '){if(chosen>=0&&chosen<current.length)select(chosen,current[chosen]);return;}chosen=Math.max(0,Math.min(current.length-1,event.key==='Home'?0:event.key==='End'?current.length-1:chosen+(event.key==='ArrowUp'?-1:1)));if(chosen*rowHeight<element.scrollTop)element.scrollTop=chosen*rowHeight;else if((chosen+1)*rowHeight>element.scrollTop+element.clientHeight)element.scrollTop=(chosen+1)*rowHeight-element.clientHeight;update();pool.find(row=>Number(row.dataset.index)===chosen)?.focus();select(chosen,current[chosen]);}
  element.addEventListener('scroll',update);element.addEventListener('keydown',key);const observer=new ResizeObserver(update);observer.observe(element);update();return {update,items(next){current=next;chosen=Math.min(chosen,current.length-1);update();},selection(index){chosen=index;update();},dispose(){disposed=true;observer.disconnect();element.removeEventListener('scroll',update);element.removeEventListener('keydown',key);element.replaceChildren();},get count(){return pool.length;}};
}
